// Start a run only when an issue gets the "factory" label.
const event = $('Linear Trigger').first().json;
const settings = $('Factory settings').first().json;
const issue = event.data ?? {};
const labels = Array.isArray(issue.labels) ? issue.labels : [];
const labelName = (label) => String(label?.name ?? '').trim().toLowerCase();
const factoryLabel = labels.find((label) => labelName(label) === 'factory');
const previousLabelIds = event.updatedFrom?.labelIds;
const labelAdded =
	event.action === 'update' &&
	Array.isArray(previousLabelIds) &&
	!previousLabelIds.includes(factoryLabel?.id);
if (event.type !== 'Issue' || !factoryLabel || !(event.action === 'create' || labelAdded)) {
	return [];
}

// The acceptance criteria are the first list below an "Acceptance criteria" heading.
// An indented item or line adds to the criterion above it. Other text ends the list.
const description = String(issue.description ?? '');
const lines = description.split(/\r?\n/);
const isHeading = (line) => /^(#{1,6}\s+\S|\*\*[^*]+\*\*:?$)/.test(line.trim());
const start = lines.findIndex((line) =>
	/^(#{1,6}\s*)?(\*\*)?acceptance criteria:?(\*\*)?:?$/i.test(line.trim()),
);
const acceptanceCriteria = [];
let listIndent = -1;
for (const line of start === -1 ? [] : lines.slice(start + 1)) {
	if (isHeading(line)) break;
	if (!line.trim()) continue;
	const item = /^(\s*)(?:[-*+]|\d+[.)])\s+(?:\[[ xX]\](?:\s+|$))?(.*)$/.exec(line);
	const indent = (item ? item[1] : /^\s*/.exec(line)[0]).length;
	const text = (item ? item[2] : line).trim();
	if (listIndent === -1) {
		// Text before the list is not a criterion.
		if (item && text) {
			listIndent = indent;
			acceptanceCriteria.push(text);
		}
		continue;
	}
	if (indent > listIndent) {
		if (text) acceptanceCriteria[acceptanceCriteria.length - 1] += (item ? '; ' : ' ') + text;
		continue;
	}
	if (!item) break;
	if (text) acceptanceCriteria.push(text);
}

// A "budget:<lines>" label replaces the default diff budget.
const budgetLabel = labels.map(labelName).find((name) => /^budget:[1-9]\d*$/.test(name));
const diffBudget = budgetLabel
	? Number(budgetLabel.slice('budget:'.length))
	: Number(settings.defaultDiffBudget);

// Each run gets its own branch, so two runs for one ticket never share a branch.
const ticket = String(issue.identifier ?? issue.id);
return [
	{
		json: {
			ticketId: String(issue.id),
			ticket,
			title: String(issue.title ?? ''),
			description,
			url: String(issue.url ?? event.url ?? ''),
			acceptanceCriteria,
			diffBudget,
			branch: 'factory/' + ticket.toLowerCase() + '-' + $execution.id,
			runKey: 'factory-' + $execution.id,
		},
	},
];

