// Facts for the gate "Ready for PR?". Minimise may only remove changes. So each file and each
// changed line after Minimise must also be in the change that the critic approved.
const checked = $('Re-verify').last().json.structuredContent;
const minimised = $('Get minimised diff').last().json.structuredContent;
const approved = $('Get diff').last().json.structuredContent;

const changesOf = (content) => (Array.isArray(content?.changes) ? content.changes : []);
const countOf = (value) => Number(value) || 0;
const linesOf = (changes) =>
	changes.reduce((total, change) => total + countOf(change?.additions) + countOf(change?.deletions), 0);

// Git writes these lines before the hunks of a file. A change of them is a change of the file.
const MODE_LINE = /^(?:old mode |new mode |new file mode |deleted file mode |rename from |rename to )/;

// Each added or deleted line of a unified diff, as "path: +line" or "path: -line". A file without
// hunks (a binary file, a mode change or a rename) is one change: its header lines. A file with
// hunks still counts its mode and rename lines.
const changedLinesOf = (diff) => {
	const result = [];
	let header = [];
	let path = '';
	let inHunk = false;
	const endFile = () => {
		if (header.length === 0) return;
		if (!inHunk) result.push(header.join(' '));
		else result.push(...header.filter((line) => MODE_LINE.test(line)).map((line) => path + ': ' + line));
	};
	for (const line of String(diff ?? '').split('\n')) {
		if (line.startsWith('diff --git ')) {
			endFile();
			header = [line];
			path = '';
			inHunk = false;
		} else if (inHunk) {
			if (/^[+-]/.test(line)) result.push(path + ': ' + line);
		} else if (line.startsWith('@@')) {
			inHunk = true;
		} else if (line !== '') {
			header.push(line);
			// git adds a tab after a name with a space. A quoted name matches no listed change.
			const name = /^(?:---|\+\+\+) (?:[ab]\/)?(.+?)\t?$/.exec(line)?.[1];
			if (name !== undefined && name !== '/dev/null') path = name;
		}
	}
	endFile();
	return result;
};

// The entries of `entries` that `reviewed` does not hold. A repeated entry needs as many copies.
const notReviewed = (entries, reviewed) => {
	const left = new Map();
	for (const entry of reviewed) left.set(entry, (left.get(entry) ?? 0) + 1);
	return entries.filter((entry) => {
		const count = left.get(entry) ?? 0;
		left.set(entry, count - 1);
		return count < 1;
	});
};

// The added and deleted lines of each file of a unified diff, with the path of each file.
const fileCounts = (diff) => {
	const files = [];
	let current;
	let inHunk = false;
	for (const line of diff.split('\n')) {
		if (line.startsWith('diff --git ')) {
			// A file without hunks (a binary file or a mode change) has no +++ line. Its header
			// gives the path, which is exact unless a path contains " b/".
			const rest = line.slice('diff --git a/'.length);
			const split = rest.lastIndexOf(' b/');
			current = { path: split === -1 ? rest : rest.slice(split + 3), additions: 0, deletions: 0 };
			files.push(current);
			inHunk = false;
		} else if (current !== undefined) {
			if (inHunk) {
				if (line.startsWith('+')) current.additions += 1;
				else if (line.startsWith('-')) current.deletions += 1;
			} else if (line.startsWith('@@')) {
				inHunk = true;
			} else {
				// The +++ line names the new path. A deleted file has /dev/null there.
				// git adds a tab after a name with a space. A quoted name matches no listed change.
				const name = /^(?:---|\+\+\+) (?:[ab]\/)?(.+?)\t?$/.exec(line)?.[1];
				if (name !== undefined && name !== '/dev/null') current.path = name;
			}
		}
	}
	return files;
};

// Each reason why a diff does not show exactly the listed changes. The diff must hold each listed
// file with the same added and deleted line counts, and no other file.
const diffProblems = (content) => {
	const changes = Array.isArray(content?.changes) ? content.changes : [];
	const problems = content?.truncated === true ? ['the diff is truncated'] : [];
	const files = fileCounts(String(content?.diff ?? ''));
	const counted = new Map();
	for (const file of files) {
		if (counted.has(file.path)) problems.push(file.path + ': appears twice in the diff');
		counted.set(file.path, file);
	}
	const listed = new Map();
	for (const change of changes) {
		const path = String(change?.path);
		if (listed.has(path)) problems.push(path + ': listed twice');
		listed.set(path, change);
	}
	for (const path of counted.keys()) {
		if (!listed.has(path)) problems.push(path + ': not in the list of changed files');
	}
	for (const [path, change] of listed) {
		const file = counted.get(path);
		const additions = Number(change?.additions);
		const deletions = Number(change?.deletions);
		if (!file) problems.push(path + ': missing from the diff');
		else if (file.additions !== additions || file.deletions !== deletions) {
			problems.push(
				path + ': the diff has ' + file.additions + ' added and ' + file.deletions +
					' deleted lines, the list has ' + additions + ' and ' + deletions,
			);
		}
	}
	return problems;
};

const approvedFiles = new Map(changesOf(approved).map((change) => [String(change?.path), change]));
// The budget and the file checks use the changes of the minimised diff, which diffProblems checks.
// The check after Minimise must list the same changes. Otherwise its list is stale or incomplete.
const minimisedChanges = changesOf(minimised);
const keyOf = (change) =>
	JSON.stringify([
		String(change?.path),
		String(change?.status),
		countOf(change?.additions),
		countOf(change?.deletions),
	]);
const sameChanges = (left, right) => {
	const keys = (list) => list.map(keyOf).sort().join('\n');
	return keys(left) === keys(right);
};
const checkProblems =
	Array.isArray(checked?.changes) && sameChanges(checked.changes, minimisedChanges)
		? []
		: ['the check after Minimise lists other changes than the minimised diff'];
const fileProblems = minimisedChanges.flatMap((change) => {
	const path = String(change?.path);
	const before = approvedFiles.get(path);
	if (!before) return [path + ': a file that the critic did not review'];
	const grew =
		countOf(change.additions) > countOf(before.additions) ||
		countOf(change.deletions) > countOf(before.deletions);
	return grew ? [path + ': more changed lines than the critic reviewed'] : [];
});

return [
	{
		json: {
			hasResult: typeof checked?.check === 'string' && typeof minimised?.diff === 'string',
			check: typeof checked?.check === 'string' ? checked.check : '',
			test: typeof checked?.test === 'string' ? checked.test : '',
			changedLines: linesOf(minimisedChanges),
			approvedLines: linesOf(changesOf(approved)),
			diffBudget: Number($('Read factory ticket').first().json.diffBudget),
			unreviewed: [
				...checkProblems,
				...fileProblems,
				...notReviewed(changedLinesOf(minimised?.diff), changedLinesOf(approved?.diff)),
				...diffProblems(minimised),
			],
		},
	},
];

