parameters.jsCode:
// One record for each run, whatever the outcome.
const outcome = $input.first().json;
const ticket = $('Read factory ticket').first().json;
// last(0) reads the success output. Without an output index, n8n can read the error output
// of these nodes, because this node is also behind their error outputs.
const successJson = (node) => (node.isExecuted ? node.last(0)?.json : undefined);
const check =
	successJson($('Re-verify'))?.structuredContent ?? successJson($('Verify'))?.structuredContent;
const changes = Array.isArray(check?.changes) ? check.changes : [];
const changedLines = changes.reduce(
	(total, change) => total + (Number(change?.additions) || 0) + (Number(change?.deletions) || 0),
	0,
);
return [
	{
		json: {
			ticket: ticket.ticket,
			ticketUrl: ticket.url,
			status: outcome.status,
			summary: outcome.summary,
			criticVerdict: successJson($('Fresh critic'))?.structuredOutput?.verdict ?? '',
			linesChanged: changedLines,
			prUrl: outcome.prUrl ?? '',
			executionId: String($execution.id),
			finishedAt: new Date().toISOString(),
		},
	},
];

